// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { PauseIcon, PlayIcon, SquareIcon } from 'lucide-react'

import {
  Bar,
  BrowserChrome,
  DemoStage,
  DockHeader,
  Label,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, PARAGRAPH, WORDS } from './script'

const BARS = 22
const seeded = (seed: number) => () => {
  seed = (seed * 16807) % 2147483647
  return seed / 2147483647
}

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  moveTo,
  click,
  count,
  wait,
  cursorOut,
}) => {
  const words = qa('w')
  const bars = qa('bar')
  const speak = (from: number, to: number, gap: number) => {
    const start = tl.duration()
    for (let i = from; i < to; i += 1) {
      const at = start + (i - from) * gap
      tl.to(
        words[i],
        { backgroundColor: 'rgba(129,140,248,0.4)', color: '#ffffff', duration: 0.06 },
        at,
      )
      tl.to(words[i], { backgroundColor: 'rgba(129,140,248,0)', duration: 0.2 }, at + gap)
    }
    const span = (to - from) * gap
    const random = seeded(from + 7)
    bars.forEach((bar) => {
      const frames = Array.from({ length: Math.ceil(span / 0.14) }, () => ({
        scaleY: 0.2 + random() * 0.8,
        duration: 0.14,
      }))
      tl.to(bar, { keyframes: frames, ease: 'sine.inOut' }, start)
    })
  }

  step(0)
  move('tab-page', { at: 0.3 })
  click('tab-page')
  tl.to(
    q('para'),
    {
      boxShadow: '0 0 0 2px rgba(129,140,248,0.8)',
      backgroundColor: 'rgba(129,140,248,0.08)',
      duration: 0.3,
    },
    '<',
  )
  tl.fromTo(words, { opacity: 0 }, { opacity: 1, duration: 0.04, stagger: 0.02 }, '<0.2')

  step(1, '+=0.4')
  move('play')
  click('play')
  tl.to(q('play-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('pause-icon'), { opacity: 1, duration: 0.1 }, '<')
  speak(0, 8, 0.26)

  step(2)
  move('knob')
  const knob = pos('knob')
  tl.to(q('knob'), { x: 38, duration: 0.5, ease: 'power2.inOut' })
  moveTo(knob.x + 38, knob.y, { at: '<', duration: 0.5 })
  count('speed', 1.5, { at: '<', from: 1, duration: 0.5, decimals: 1, suffix: '×' })
  speak(8, WORDS.length - 2, 0.15)

  step(3)
  move('play')
  click('play')
  tl.to(q('pause-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('play-icon'), { opacity: 1, duration: 0.1 }, '<')
  tl.to(bars, { scaleY: 0.12, duration: 0.4, stagger: 0.01 }, '<')
  tl.fromTo(q('paused'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '<')
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Read Aloud reading page text with word highlighting, a waveform and a speed control"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://blog.example/writing-tips"
        panelWidth={210}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="space-y-2.5 p-3">
              <div className="flex rounded-lg border border-line bg-canvas/60 p-0.5 text-[10px]">
                <span
                  data-d="tab-page"
                  className="flex-1 rounded-md bg-[var(--accent)]/25 px-2 py-1 text-center text-ink"
                >
                  Page
                </span>
                <span className="flex-1 px-2 py-1 text-center text-muted">Selection</span>
                <span className="flex-1 px-2 py-1 text-center text-muted">Your text</span>
              </div>
              <p className="h-[82px] overflow-hidden rounded-lg border border-line bg-canvas/70 p-2 text-[10px] leading-[16px] text-ink-soft">
                {WORDS.map((word, index) => (
                  <span key={index}>
                    <span data-d="w" className="rounded-sm opacity-0">
                      {word}
                    </span>{' '}
                  </span>
                ))}
              </p>
              <div className="flex h-8 items-center justify-center gap-[3px]">
                {Array.from({ length: BARS }, (_, index) => (
                  <span
                    key={index}
                    data-d="bar"
                    className="h-full w-[4px] origin-center scale-y-[0.12] rounded-full bg-[var(--accent)]"
                  />
                ))}
              </div>
              <div className="flex items-center justify-center gap-2">
                <span
                  data-d="play"
                  className="relative flex size-9 items-center justify-center rounded-full bg-[var(--accent)] text-canvas"
                >
                  <PlayIcon data-d="play-icon" className="absolute size-4" />
                  <PauseIcon data-d="pause-icon" className="absolute size-4 opacity-0" />
                </span>
                <span className="flex size-7 items-center justify-center rounded-full border border-line-strong text-muted">
                  <SquareIcon className="size-3" />
                </span>
              </div>
              <div>
                <div className="flex justify-between text-[10px]">
                  <Label>Speech rate</Label>
                  <span data-d="speed" className="font-mono text-ink">
                    1.0×
                  </span>
                </div>
                <div className="relative mt-2 h-1 rounded-full bg-ink/10">
                  <span
                    data-d="knob"
                    className="absolute -top-1.5 left-[30%] size-4 rounded-full border-2 border-[var(--accent)] bg-canvas"
                  />{' '}
                </div>
              </div>
              <p data-d="paused" className="text-center text-[10px] text-muted opacity-0">
                Paused · position kept
              </p>
            </div>
          </div>
        }
      >
        <div className="h-full bg-[#fafafa] px-5 pt-4 text-[#111]">
          <p className="text-[8px] uppercase tracking-[0.2em] text-[#7c3aed]">Writing</p>
          <h3 className="text-[15px] font-bold leading-tight tracking-tight">
            Read your draft out loud
          </h3>
          <div className="mt-2 space-y-1.5">
            <Bar w="92%" className="bg-black/15" />
            <Bar w="84%" className="bg-black/15" />
          </div>
          <p
            data-d="para"
            className="-mx-1.5 mt-3 rounded-md px-1.5 py-1 text-[10.5px] leading-relaxed text-[#333]"
          >
            {PARAGRAPH}
          </p>
          <div className="mt-3 space-y-1.5">
            <Bar w="90%" className="bg-black/15" />
            <Bar w="95%" className="bg-black/15" />
            <Bar w="70%" className="bg-black/15" />
            <Bar w="88%" className="bg-black/15" />
          </div>
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
